3: use core::ops::Range;
4: 
5: use super::{Interval, Vmar, util::get_intersected_range};
6: use crate::{prelude::*, vm::perms::VmPerms};
7: 
8: impl Vmar {
9:     /// Change the permissions of the memory mappings in the specified range.
10:     ///
11:     /// The range's start and end addresses must be page-aligned.
12:     ///
13:     /// If the range contains unmapped pages, an [`ENOMEM`] error will be returned.
14:     /// Note that pages before the unmapped hole are still protected.
15:     ///
16:     /// [`ENOMEM`]: Errno::ENOMEM
17:     pub fn protect(&self, perms: VmPerms, range: Range<usize>) -> Result<()> {
18:         debug_assert!(range.start.is_multiple_of(PAGE_SIZE));
19:         debug_assert!(range.end.is_multiple_of(PAGE_SIZE));
20: 
21:         let mut inner = self.inner.write();
22:         let vm_space = self.vm_space();
23: 
24:         let mut protect_mappings = Vec::new();
25: 
26:         for vm_mapping in inner.vm_mappings.find(&range) {
27:             protect_mappings.push((vm_mapping.range(), vm_mapping.perms()))
28:         }
29: 
30:         let mut last_mapping_end = range.start;
31:         for (vm_mapping_range, vm_mapping_perms) in protect_mappings {
32:             if last_mapping_end < vm_mapping_range.start {
33:                 return_errno_with_message!(
34:                     Errno::ENOMEM,
35:                     "the range contains pages that are not mapped"
36:                 );
37:             }
38:             last_mapping_end = vm_mapping_range.end;
39: 
40:             if perms == vm_mapping_perms & VmPerms::ALL_PERMS {
41:                 continue;
42:             }
43:             let new_perms = perms | (vm_mapping_perms & VmPerms::ALL_MAY_PERMS);
44:             new_perms.check()?;
45: 
46:             let vm_mapping = inner.remove(&vm_mapping_range.start).unwrap();
47:             let vm_mapping_range = vm_mapping.range();
48:             let intersected_range = get_intersected_range(&range, &vm_mapping_range);
49: 
50:             // Protects part of the taken `VmMapping`.
51:             let (left, taken, right) = vm_mapping.split_range(&intersected_range);
52: 
53:             // Puts the rest back.
54:             if let Some(left) = left {
55:                 inner.insert_without_try_merge(left);
56:             }
57:             if let Some(right) = right {
58:                 inner.insert_without_try_merge(right);
59:             }
60: 
61:             // Protects part of the `VmMapping`.
62:             let taken = taken.protect(vm_space.as_ref(), new_perms);
63:             inner.insert_try_merge(taken);
64:         }
65: 
66:         if last_mapping_end < range.end {
67:             return_errno_with_message!(
68:                 Errno::ENOMEM,
69:                 "the range contains pages that are not mapped"
70:             );
71:         }
72: 
73:         Ok(())
74:     }
75: }

