10: impl Vmar {
11:     /// Clears all mappings.
12:     ///
13:     /// After being cleared, this vmar will become an empty vmar
14:     #[expect(dead_code)] // TODO: This should be called when the last process drops the VMAR.
15:     pub fn clear(&self) {
16:         let mut inner = self.inner.write();
17:         inner.vm_mappings.clear();
18: 
19:         // Keep `inner` locked to avoid race conditions.
20:         let preempt_guard = disable_preempt();
21:         let full_range = 0..VMAR_CAP_ADDR;
22:         let mut cursor = self
23:             .vm_space
24:             .cursor_mut(&preempt_guard, &full_range)
25:             .unwrap();
26:         cursor.unmap(full_range.len());
27:         cursor.flusher().sync_tlb_flush();
28:     }
29: 
30:     /// Destroys all mappings that fall within the specified
31:     /// range in bytes.
32:     ///
33:     /// The range's start and end addresses must be page-aligned.
34:     ///
35:     /// Mappings may fall partially within the range; only the overlapped
36:     /// portions of the mappings are unmapped.
37:     pub fn remove_mapping(&self, range: Range<usize>) -> Result<()> {
38:         debug_assert!(range.start.is_multiple_of(PAGE_SIZE));
39:         debug_assert!(range.end.is_multiple_of(PAGE_SIZE));
40: 
41:         let mut inner = self.inner.write();
42:         let mut rss_delta = RssDelta::new(self);
43:         inner.alloc_free_region_exact_truncate(
44:             &self.vm_space,
45:             range.start,
46:             range.len(),
47:             &mut rss_delta,
48:         )?;
49:         Ok(())
50:     }
51: }

