9: pub fn sys_madvise(addr: Vaddr, len: usize, behavior: i32, ctx: &Context) -> Result<SyscallReturn> {
10:     let behavior = MadviseBehavior::try_from(behavior)?;
11:     debug!(
12:         "addr = 0x{:x}, len = 0x{:x}, behavior = {:?}",
13:         addr, len, behavior
14:     );
15: 
16:     if !addr.is_multiple_of(PAGE_SIZE) {
17:         return_errno_with_message!(Errno::EINVAL, "the mapping address is not aligned");
18:     }
19:     if len == 0 {
20:         return Ok(SyscallReturn::Return(0));
21:     }
22:     if VMAR_CAP_ADDR.checked_sub(addr).is_none_or(|gap| gap < len) {
23:         // FIXME: Linux returns `EINVAL` if `(addr + len).align_up(PAGE_SIZE)` overflows. Here, we
24:         // perform a stricter validation.
25:         return_errno_with_message!(Errno::EINVAL, "the mapping range is not in userspace");
26:     }
27:     let addr_range = addr..(addr + len).align_up(PAGE_SIZE);
28: 
29:     match behavior {
30:         MadviseBehavior::MADV_NORMAL
31:         | MadviseBehavior::MADV_SEQUENTIAL
32:         | MadviseBehavior::MADV_WILLNEED => {
33:             // perform a read at first
34:             let mut buffer = vec![0u8; addr_range.len()];
35:             ctx.user_space()
36:                 .read_bytes(addr_range.start, buffer.as_mut_slice())?;
37:         }
38:         MadviseBehavior::MADV_DONTNEED => {
39:             warn!("MADV_DONTNEED isn't implemented, do nothing for now.");
40:         }
41:         MadviseBehavior::MADV_FREE => madv_free(addr_range.start, addr_range.end, ctx)?,
42:         MadviseBehavior::MADV_NOHUGEPAGE => {
43:             warn!("MADV_NOHUGEPAGE isn't implemented, do nothing for now");
44:         }
45:         MadviseBehavior::MADV_HUGEPAGE => {
46:             warn!("MADV_HUGEPAGE isn't implemented, do nothing for now");
47:         }
48:         MadviseBehavior::MADV_MERGEABLE => {
49:             warn!("MADV_MERGEABLE isn't implemented, do nothing for now");
50:         }
51:         MadviseBehavior::MADV_DONTFORK => {
52:             warn!("MADV_DONTFORK isn't implemented, do nothing for now");
53:         }
54:         _ => todo!(),
55:     }
56:     Ok(SyscallReturn::Return(0))
57: }
58: 
59: fn madv_free(start: Vaddr, end: Vaddr, ctx: &Context) -> Result<()> {
60:     let user_space = ctx.user_space();
61:     let vmar = user_space.vmar();
62:     let advised_range = start..end;
63:     let _ = vmar.remove_mapping(advised_range);
64: 
65:     Ok(())
66: }
