70:     /// Returns the new program break on success, or the current program break on failure.
71:     /// This behavior is consistent with the Linux `brk` syscall.
72:     pub fn set_program_break(
73:         &self,
74:         new_program_break: Vaddr,
75:         ctx: &Context,
76:     ) -> core::result::Result<Vaddr, Vaddr> {
77:         let user_space = ctx.user_space();
78:         let vmar = user_space.vmar();
79: 
80:         let current_program_break = self.current_program_break.load(Ordering::Acquire);
81: 
82:         // According to the Linux source code, when the `brk` value is more than the
83:         // rlimit, the `brk` syscall returns the current `brk` value.
84:         // Reference: <https://elixir.bootlin.com/linux/v6.16.9/source/mm/mmap.c#L152>
85:         if new_program_break > self.base + self.limit {
86:             return Err(current_program_break);
87:         }
88:         if new_program_break < current_program_break {
89:             // FIXME: should we allow shrink current user heap?
90:             return Ok(current_program_break);
91:         }
92: 
93:         let current_program_break_aligned = current_program_break.align_up(PAGE_SIZE);
94:         let new_program_break_aligned = new_program_break.align_up(PAGE_SIZE);
95: 
96:         // No need to expand the heap.
97:         if new_program_break_aligned == current_program_break_aligned {
98:             self.current_program_break
99:                 .store(new_program_break, Ordering::Release);
100:             return Ok(new_program_break);
101:         }
102: 
103:         // Remove the reserved space.
104:         vmar.remove_mapping(current_program_break_aligned..new_program_break_aligned)
105:             .map_err(|_| current_program_break)?;
106: 
107:         let old_size = current_program_break_aligned - self.base;
108:         let new_size = new_program_break_aligned - self.base;
109:         // Expand the heap.
110:         vmar.resize_mapping(self.base, old_size, new_size, false)
111:             .map_err(|_| current_program_break)?;
112: 
113:         self.current_program_break
114:             .store(new_program_break, Ordering::Release);
115:         Ok(new_program_break)
116:     }
117: 
118:     pub(super) fn set_uninitialized(&self) {
119:         self.current_program_break
120:             .store(self.base + PAGE_SIZE, Ordering::Relaxed);
121:     }
122: }
