666: impl VmMapping {
667:     /// Unmaps the mapping from the VM space,
668:     /// and returns the number of unmapped pages.
669:     pub(super) fn unmap(self, vm_space: &VmSpace) -> usize {
670:         let preempt_guard = disable_preempt();
671:         let range = self.range();
672:         let mut cursor = vm_space.cursor_mut(&preempt_guard, &range).unwrap();
673: 
674:         let num_unmapped = cursor.unmap(range.len());
675:         cursor.flusher().dispatch_tlb_flush();
676:         cursor.flusher().sync_tlb_flush();
677: 
678:         num_unmapped
679:     }
680: 
681:     /// Change the perms of the mapping.
682:     pub(super) fn protect(self, vm_space: &VmSpace, perms: VmPerms) -> Self {
683:         let mut new_flags = PageFlags::from(perms);
684:         if self.is_cow() && !self.perms.contains(VmPerms::WRITE) {
685:             new_flags.remove(PageFlags::W);
686:         }
687: 
688:         let preempt_guard = disable_preempt();
689:         let range = self.range();
690:         let mut cursor = vm_space.cursor_mut(&preempt_guard, &range).unwrap();
691: 
692:         let op = |flags: &mut PageFlags, _cache: &mut CachePolicy| *flags = new_flags;
693:         while cursor.virt_addr() < range.end {
694:             if let Some(va) = cursor.protect_next(range.end - cursor.virt_addr(), op) {
695:                 cursor.flusher().issue_tlb_flush(TlbFlushOp::for_range(va));
696:             } else {
697:                 break;
698:             }
699:         }
700:         cursor.flusher().dispatch_tlb_flush();
701:         cursor.flusher().sync_tlb_flush();
702: 
703:         Self { perms, ..self }
704:     }
705: }
