852: /// Attempts to merge two [`VmMapping`]s into a single mapping if they are
853: /// adjacent and compatible.
854: ///
855: /// - Returns the merged [`VmMapping`] if successful. The caller should
856: ///   remove the original mappings before inserting the merged mapping
857: ///   into the [`Vmar`].
858: /// - Returns `None` otherwise.
859: fn try_merge(left: &VmMapping, right: &VmMapping) -> Option<VmMapping> {
860:     let is_adjacent = left.map_end() == right.map_to_addr();
861:     let is_type_equal = left.is_shared == right.is_shared
862:         && left.handle_page_faults_around == right.handle_page_faults_around
863:         && left.perms == right.perms;
864: 
865:     if !is_adjacent || !is_type_equal {
866:         return None;
867:     }
868: 
869:     let mapped_mem = match (&left.mapped_mem, &right.mapped_mem) {
870:         (MappedMemory::Anonymous, MappedMemory::Anonymous) => {
871:             // Anonymous memory mappings can be merged if they are adjacent
872:             MappedMemory::Anonymous
873:         }
874:         (MappedMemory::Vmo(l_vmo_obj), MappedMemory::Vmo(r_vmo_obj)) => {
875:             let l_vmo = l_vmo_obj.vmo();
876:             let r_vmo = r_vmo_obj.vmo();
877: 
878:             if Arc::ptr_eq(l_vmo, r_vmo) {
879:                 let is_offset_contiguous =
880:                     l_vmo_obj.offset() + left.map_size() == r_vmo_obj.offset();
881:                 if !is_offset_contiguous {
882:                     return None;
883:                 }
884:                 MappedMemory::Vmo(l_vmo_obj.dup())
885:             } else {
886:                 return None;
887:             }
888:         }
889:         // Device memory and other types cannot be merged
890:         _ => return None,
891:     };
892: 
893:     let map_size = NonZeroUsize::new(left.map_size() + right.map_size()).unwrap();
894: 
895:     Some(VmMapping {
896:         map_size,
897:         mapped_mem,
898:         inode: left.inode.clone(),
899:         ..*left
900:     })
901: }
