48:     fn from(rights: Rights) -> VmPerms {
49:         let mut vm_perm = VmPerms::empty();
50:         if rights.contains(Rights::READ) {
51:             vm_perm |= VmPerms::READ;
52:         }
53:         if rights.contains(Rights::WRITE) {
54:             vm_perm |= VmPerms::WRITE;
55:         }
56:         if rights.contains(Rights::EXEC) {
57:             vm_perm |= VmPerms::EXEC;
58:         }
59:         vm_perm
