8: /// The interval of an item in an interval set.
9: ///
10: /// All items in the interval set must have a range.
11: pub trait Interval<K: Clone> {
12:     /// Returns the range of the interval.
13:     fn range(&self) -> Range<K>;
14: }
15: 
16: /// A collection that contains non-overlapping intervals as items.
17: ///
18: /// In particular, the collection allows one to retrieve interval items that
19: /// intersect with a point of value or range of values.
20: #[derive(Debug)]
21: pub struct IntervalSet<K, V>
22: where
23:     K: Clone + Ord,
24:     V: Interval<K>,
25: {
26:     btree: BTreeMap<K, V>,
27: }
28: 
29: impl<K, V> Default for IntervalSet<K, V>
30: where
31:     K: Clone + Ord,
32:     V: Interval<K>,
33: {
34:     fn default() -> Self {
35:         Self::new()
36:     }
37: }
38: 
39: impl<K, V> IntervalSet<K, V>
40: where
41:     K: Clone + Ord,
42:     V: Interval<K>,
43: {
44:     /// Creates a new interval set.
45:     pub const fn new() -> Self {
46:         Self {
47:             btree: BTreeMap::new(),
48:         }
49:     }
50: 
51:     /// Inserts an interval item into the interval set.
52:     pub fn insert(&mut self, item: V) {
53:         let range = item.range();
54:         self.btree.insert(range.start, item);
55:     }
56: 
57:     /// Removes an interval item from the interval set.
58:     pub fn remove(&mut self, key: &K) -> Option<V> {
59:         self.btree.remove(key)
60:     }
61: 
62:     /// Returns an iterator over the interval items in the interval set.
63:     pub fn iter(&self) -> impl DoubleEndedIterator<Item = &V> {
64:         self.btree.values()
65:     }
66: 
67:     /// Finds an interval item that contains the given point.
68:     ///
69:     /// If no such item exists, returns [`None`]. Otherwise, returns the item
70:     /// that contains the point.
71:     pub fn find_one(&self, point: &K) -> Option<&V> {
72:         let cursor = self.btree.lower_bound(core::ops::Bound::Excluded(point));
73:         // There's only one previous element that may contain the point.
74:         // If it doesn't, there's no other chances.
75:         cursor
76:             .peek_prev()
77:             .and_then(|(_, v)| (v.range().end > *point).then_some(v))
