16: pub fn sys_mmap(
17:     addr: u64,
18:     len: u64,
19:     perms: u64,
20:     flags: u64,
21:     fd: u64,
22:     offset: u64,
23:     ctx: &Context,
24: ) -> Result<SyscallReturn> {
25:     let perms = VmPerms::from_bits_truncate(perms as u32);
26:     let option = MMapOptions::try_from(flags as u32)?;
27:     let res = do_sys_mmap(
28:         addr as usize,
29:         len as usize,
30:         perms,
31:         option,
32:         fd as _,
33:         offset as usize,
34:         ctx,
35:     )?;
36:     Ok(SyscallReturn::Return(res as _))
37: }
38: 
39: fn do_sys_mmap(
40:     addr: Vaddr,
41:     len: usize,
42:     vm_perms: VmPerms,
43:     option: MMapOptions,
44:     fd: FileDesc,
45:     offset: usize,
46:     ctx: &Context,
47: ) -> Result<Vaddr> {
48:     debug!(
49:         "addr = 0x{:x}, len = 0x{:x}, perms = {:?}, option = {:?}, fd = {}, offset = 0x{:x}",
50:         addr, len, vm_perms, option, fd, offset
51:     );
52: 
53:     let len = check_len(len)?;
54:     check_addr(addr, len, option.flags())?;
55:     check_offset(offset, len, option.flags())?;
56: 
57:     // On x86_64 and riscv64, `PROT_WRITE` implies `PROT_READ`.
58:     // Reference:
59:     // <https://man7.org/linux/man-pages/man2/mmap.2.html>,
60:     // Section 5.11.3 from <https://www.intel.com/content/dam/www/public/us/en/documents/manuals/64-ia-32-architectures-software-developer-vol-3a-part-1-manual.pdf>,
61:     // <https://riscv.github.io/riscv-isa-manual/snapshot/privileged/#translation>.
62:     #[cfg(any(target_arch = "x86_64", target_arch = "riscv64"))]
63:     let vm_perms = if !vm_perms.contains(VmPerms::READ) && vm_perms.contains(VmPerms::WRITE) {
64:         vm_perms | VmPerms::READ
65:     } else {
66:         vm_perms
67:     };
68: 
69:     let mut vm_may_perms = VmPerms::ALL_MAY_PERMS;
70: 
71:     let user_space = ctx.user_space();
72:     let vmar = user_space.vmar();
73:     let vm_map_options = {
74:         let mut options = vmar.new_map(len, vm_perms)?;
75: 
76:         if option.flags().is_fixed() {
77:             options = options.offset(addr);
78:             if !option.flags().contains(MMapFlags::MAP_FIXED_NOREPLACE) {
79:                 options = options.can_overwrite(true);
80:             }
81:         } else if option.flags().contains(MMapFlags::MAP_32BIT) {
82:             // TODO: Support MAP_32BIT. MAP_32BIT requires the mapping address to be below 2 GiB.
83:             warn!("MAP_32BIT is not supported");
84:         }
85: 
86:         if option.typ().is_shared() {
87:             options = options.is_shared(true);
88:         }
89: 
90:         if option.flags().contains(MMapFlags::MAP_ANONYMOUS) {
91:             // Anonymous shared mappings should share the same memory pages.
92:             if option.typ().is_shared() {
93:                 let shared_vmo = {
94:                     let vmo_options = VmoOptions::new(len);
95:                     vmo_options.alloc()?
96:                 };
97:                 options = options.vmo(shared_vmo);
98:             }
99:         } else {
100:             let mut file_table = ctx.thread_local.borrow_file_table_mut();
101:             let file = get_file_fast!(&mut file_table, fd);
102: 
103:             let access_mode = file.access_mode();
104:             if vm_perms.contains(VmPerms::READ) && !access_mode.is_readable() {
105:                 return_errno_with_message!(Errno::EACCES, "the file is not opened readable");
106:             }
107:             if option.typ() == MMapType::Shared && !access_mode.is_writable() {
108:                 if vm_perms.contains(VmPerms::WRITE) {
109:                     return_errno_with_message!(Errno::EACCES, "the file is not opened writable");
110:                 }
111:                 vm_may_perms.remove(VmPerms::MAY_WRITE);
112:             }
113: 
114:             options = options
115:                 .may_perms(vm_may_perms)
116:                 .mappable(file.mappable()?)
117:                 .vmo_offset(offset)
118:                 .handle_page_faults_around();
119:         }
120: 
121:         options
122:     };
123: 
124:     let map_addr = vm_map_options.build()?;
125: 
126:     Ok(map_addr)
127: }
