129: fn check_len(len: usize) -> Result<usize> {
130:     if len == 0 {
131:         return_errno_with_message!(Errno::EINVAL, "the mapping length is zero");
132:     }
133: 
134:     if len > VMAR_CAP_ADDR {
135:         return_errno_with_message!(Errno::ENOMEM, "the mapping length is too large");
136:     }
137: 
138:     Ok(len.align_up(PAGE_SIZE))
139: }
140: 
141: fn check_addr(addr: Vaddr, len: usize, flags: MMapFlags) -> Result<()> {
142:     if !flags.is_fixed() {
143:         return Ok(());
144:     }
145: 
146:     if !addr.is_multiple_of(PAGE_SIZE) {
147:         return_errno_with_message!(Errno::EINVAL, "the mapping address is not aligned");
148:     }
149: 
150:     if addr < VMAR_LOWEST_ADDR {
151:         return_errno_with_message!(Errno::EPERM, "the mapping address is too low");
152:     }
153: 
154:     if addr > VMAR_CAP_ADDR - len {
155:         return_errno_with_message!(Errno::ENOMEM, "the mapping address is too high");
156:     }
157: 
158:     Ok(())
159: }
160: 
161: fn check_offset(offset: usize, len: usize, flags: MMapFlags) -> Result<()> {
162:     if !offset.is_multiple_of(PAGE_SIZE) {
163:         return_errno_with_message!(Errno::EINVAL, "the mapping offset is not aligned");
164:     }
165: 
166:     if flags.contains(MMapFlags::MAP_ANONYMOUS) {
167:         return Ok(());
168:     }
169: 
170:     if offset
171:         .checked_add(len)
172:         .is_none_or(|end| end >= isize::MAX as usize)
173:     {
174:         return_errno_with_message!(Errno::EOVERFLOW, "the mapping offset overflows");
175:     }
176: 
177:     Ok(())
178: }
